143	// SharedTxRow wraps a pgx.Row such that it unlocks SharedExecutor when
144	// the row finishes scanning.
145	type SharedTxRow struct {
146		sharedTxDerivative
147	
148		innerRow pgx.Row
149	}
150	
151	func (r *SharedTxRow) Scan(dest ...any) error {
152		defer r.unlockParent()
153		return r.innerRow.Scan(dest...)
154	}
