156	// SharedTxRows wraps a pgx.Rows such that it unlocks SharedExecutor when
157	// the rows are closed.
158	type SharedTxRows struct {
159		sharedTxDerivative
160	
161		innerRows pgx.Rows
162	}
163	
164	func (r *SharedTxRows) Close() {
165		defer r.unlockParent()
166		r.innerRows.Close()
167	}
