488	func (c *Conn) exec(ctx context.Context, sql string, arguments ...any) (commandTag pgconn.CommandTag, err error) {
489		mode := c.config.DefaultQueryExecMode
490		var queryRewriter QueryRewriter
491	
492	optionLoop:
493		for len(arguments) > 0 {
494			switch arg := arguments[0].(type) {
495			case QueryExecMode:
496				mode = arg
497				arguments = arguments[1:]
498			case QueryRewriter:
499				queryRewriter = arg
500				arguments = arguments[1:]
501			default:
502				break optionLoop
503			}
504		}
505	
506		if queryRewriter != nil {
507			sql, arguments, err = queryRewriter.RewriteQuery(ctx, c, sql, arguments)
508			if err != nil {
509				return pgconn.CommandTag{}, fmt.Errorf("rewrite query failed: %w", err)
510			}
511		}
512	
513		// Always use simple protocol when there are no arguments.
514		if len(arguments) == 0 {
515			mode = QueryExecModeSimpleProtocol
516		}
517	
518		defer func() {
519			if err != nil {
520				if sc := c.statementCache; sc != nil {
521					sc.Invalidate(sql)
522				}
523	
524				if sc := c.descriptionCache; sc != nil {
525					sc.Invalidate(sql)
526				}
527			}
528		}()
529	
530		if sd, ok := c.preparedStatements[sql]; ok {
531			return c.execPrepared(ctx, sd, arguments)
532		}
533	
534		switch mode {
535		case QueryExecModeCacheStatement:
536			if c.statementCache == nil {
537				return pgconn.CommandTag{}, errDisabledStatementCache
538			}
539			sd := c.statementCache.Get(sql)
540			if sd == nil {
541				sd, err = c.Prepare(ctx, stmtcache.StatementName(sql), sql)
542				if err != nil {
543					return pgconn.CommandTag{}, err
544				}
545				c.statementCache.Put(sd)
546			}
547	
548			return c.execPrepared(ctx, sd, arguments)
549		case QueryExecModeCacheDescribe:
550			if c.descriptionCache == nil {
551				return pgconn.CommandTag{}, errDisabledDescriptionCache
552			}
553			sd := c.descriptionCache.Get(sql)
554			if sd == nil {
555				sd, err = c.Prepare(ctx, "", sql)
556				if err != nil {
557					return pgconn.CommandTag{}, err
558				}
559				c.descriptionCache.Put(sd)
560			}
561	
562			return c.execParams(ctx, sd, arguments)
563		case QueryExecModeDescribeExec:
564			sd, err := c.Prepare(ctx, "", sql)
565			if err != nil {
566				return pgconn.CommandTag{}, err
567			}
568			return c.execPrepared(ctx, sd, arguments)
569		case QueryExecModeExec:
570			return c.execSQLParams(ctx, sql, arguments)
571		case QueryExecModeSimpleProtocol:
572			return c.execSimpleProtocol(ctx, sql, arguments)
573		default:
574			return pgconn.CommandTag{}, fmt.Errorf("unknown QueryExecMode: %v", mode)
575		}
576	}
