578	func (c *Conn) execSimpleProtocol(ctx context.Context, sql string, arguments []any) (commandTag pgconn.CommandTag, err error) {
579		if len(arguments) > 0 {
580			sql, err = c.sanitizeForSimpleQuery(sql, arguments...)
581			if err != nil {
582				return pgconn.CommandTag{}, err
583			}
584		}
585	
586		mrr := c.pgConn.Exec(ctx, sql)
587		for mrr.NextResult() {
588			commandTag, _ = mrr.ResultReader().Close()
589		}
590		err = mrr.Close()
591		return commandTag, err
592	}
593	
594	func (c *Conn) execParams(ctx context.Context, sd *pgconn.StatementDescription, arguments []any) (pgconn.CommandTag, error) {
595		err := c.eqb.Build(c.typeMap, sd, arguments)
596		if err != nil {
597			return pgconn.CommandTag{}, err
598		}
599	
600		result := c.pgConn.ExecParams(ctx, sd.SQL, c.eqb.ParamValues, sd.ParamOIDs, c.eqb.ParamFormats, c.eqb.ResultFormats).Read()
601		c.eqb.reset() // Allow c.eqb internal memory to be GC'ed as soon as possible.
602		return result.CommandTag, result.Err
